using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // EF Core 9 renamed the discriminator from "Discriminator" to "$type".
            // Preserve the old property name so existing 500K documents remain readable
            // and direct SQL queries referencing c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 stopped prefixing id values with the discriminator.
            // Old docs have "Product|123"; without this, EF would generate just "123"
            // and fail to find existing documents.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .HasConversion(
                      id => $"Product|{id}",
                      cosmosId => int.Parse(cosmosId.Replace("Product|", "")));
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

